import styled from '@emotion/styled';
import { Tabs } from 'components/UI';
import { theme } from 'theme';
import { transientShouldForwardProp } from 'utils/emotion';

export const StyledTabsList = styled(Tabs.List, {
  shouldForwardProp: transientShouldForwardProp,
})({});

export const StyledContainer = styled.div({
  paddingTop: '24px',
  display: 'flex',
  justifyContent: 'center',
  width: '100%',
});

export const StyledContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
  position: 'relative',
  flex: 1,
});

export const StyledTabContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',
});

export const StyledPageTitleContainer = styled.div({
  marginBottom: '8px',
});

export const StyledPageTitleRow = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  marginBottom: '8px',
});

export const StyledPageTitleContent = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing['2'],
});

export const StyledPageDescription = styled.p({
  fontFamily: theme.fonts.paragraph,
  fontSize: '16px',
  fontWeight: '400',
  lineHeight: '24px',
  color: theme.colors.interfaceLabelSecondary,
  margin: 0,
});

export const StyledGlobalDataBanner = styled.div({
  margin: '0rem 0rem -1rem',
  position: 'relative',
  left: '8px',
  width: '100%',
  maxWidth: '1314px',
});
